#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry euclidean. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Record point2D := mkPoint { px : R; py : R }. Definition dist (P Q : point2D) : R := sqrt ((px P - px Q)^+2 + (py P - py Q)^+2). Definition parallell (u v : point2D) := (px u) * (py v) = (py u) * (px v). Definition vec (P Q : point2D) : point2D := mkPoint (px Q - px P) (py Q - py P). Definition is_trapezoid (A B C D : point2D) : Prop := parallell (vec A B) (vec D C) /\ ~ parallell (vec B C) (vec A D). Definition area_quadrilateral (A B C D : point2D) : R := (1%:R / 2) * ((px A * py B - px B * py A) + (px B * py C - px C * py B) + (px C * py D - px D * py C) + (px D * py A - px A * py D)). Theorem trapezoid_area_positive : forall A B C D, is_trapezoid A B C D -> area_quadrilateral A B C D > 0. Proof. Admitted. End
